class MyHashMap {
    static class Node {
        int key, val;
        Node next;
        Node(int k, int v) { this.key = k; this.val = v; }
    }
    private static final int SIZE = 2069;
    private Node[] buckets;
    public MyHashMap() {
        this.buckets = new Node[SIZE];
        for (int i = 0; i < SIZE; i++) {
            this.buckets[i] = new Node(-1, -1);
        }
    }
    public void put(int key, int value) {
        int idx = key % SIZE;
        Node cur = buckets[idx];
        while (cur.next != null) {
            if (cur.next.key == key) {
                cur.next.val = value;
                return;
            }
            cur = cur.next;
        }
        cur.next = new Node(key, value);
    }
    public int get(int key) {
        int idx = key % SIZE;
        Node cur = buckets[idx].next;
        while (cur != null) {
            if (cur.key == key) return cur.val;
            cur = cur.next;
        }
        return -1;
    }
    public void remove(int key) {
        int idx = key % SIZE;
        Node cur = buckets[idx];
        while (cur.next != null) {
            if (cur.next.key == key) {
                cur.next = cur.next.next;
                return;
            }
            cur = cur.next;
        }
    }
